#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <algorithm>
#include <climits>
using namespace std;

using ll = long long;
using pii = pair<int, int>;

struct FlowEdge {
    int from, to;
    ll capacity, flow;
    FlowEdge(int f, int t, ll c) : from(f), to(t), capacity(c), flow(0) {}
};

class MaxFlowSolver {
public:
    int nodes, src, dst;
    vector<FlowEdge> edges;
    vector<vector<int>> adj;
    vector<int> level, current;
    queue<int> q;

    MaxFlowSolver(int n, int s, int d) : nodes(n), src(s), dst(d) {
        adj.resize(n);
        level.resize(n);
        current.resize(n);
    }

    void connect(int u, int v, ll cap) {
        edges.emplace_back(u, v, cap);
        edges.emplace_back(v, u, 0);
        adj[u].push_back(edges.size() - 2);
        adj[v].push_back(edges.size() - 1);
    }

    bool levelGraph() {
        fill(level.begin(), level.end(), -1);
        level[src] = 0;
        q.push(src);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int idx : adj[u]) {
                auto& e = edges[idx];
                if (e.capacity - e.flow > 0 && level[e.to] == -1) {
                    level[e.to] = level[u] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[dst] != -1;
    }

    ll augment(int u, ll flow) {
        if (u == dst) return flow;
        for (int& i = current[u]; i < (int)adj[u].size(); ++i) {
            int idx = adj[u][i];
            auto& e = edges[idx];
            if (level[e.to] == level[u] + 1 && e.capacity - e.flow > 0) {
                ll pushed = augment(e.to, min(flow, e.capacity - e.flow));
                if (pushed > 0) {
                    e.flow += pushed;
                    edges[idx ^ 1].flow -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    ll solve() {
        ll result = 0;
        while (levelGraph()) {
            fill(current.begin(), current.end(), 0);
            while (ll pushed = augment(src, LLONG_MAX)) {
                result += pushed;
            }
        }
        return result;
    }
};

int fireDist[150][150], exitDist[150][150];
int cellId[150][150];
int N, Tmax;
vector<string> cells, caps;

vector<pii> getNeighbors(int r, int c) {
    vector<pii> res;
    if (r + 1 < N) res.emplace_back(r + 1, c);
    if (r - 1 >= 0) res.emplace_back(r - 1, c);
    if (c + 1 < N) res.emplace_back(r, c + 1);
    if (c - 1 >= 0) res.emplace_back(r, c - 1);
    return res;
}

void propagateFire(int sr, int sc) {
    memset(fireDist, -1, sizeof(fireDist));
    queue<pii> q;
    fireDist[sr][sc] = 0;
    q.push({sr, sc});
    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop();
        for (auto [nr, nc] : getNeighbors(r, c)) {
            char ch = cells[nr][nc];
            if ((ch != 'Z' && !isdigit(ch)) || fireDist[nr][nc] != -1) continue;
            fireDist[nr][nc] = fireDist[r][c] + 1;
            q.push({nr, nc});
        }
    }
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (isdigit(cells[i][j]) && fireDist[i][j] == -1)
                fireDist[i][j] = Tmax;
}

void propagateExit(int sr, int sc) {
    memset(exitDist, -1, sizeof(exitDist));
    queue<pii> q;
    exitDist[sr][sc] = 0;
    q.push({sr, sc});
    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop();
        for (auto [nr, nc] : getNeighbors(r, c)) {
            if (!isdigit(cells[nr][nc]) || exitDist[nr][nc] != -1) continue;
            exitDist[nr][nc] = exitDist[r][c] + 1;
            q.push({nr, nc});
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> N >> Tmax;
    cells.resize(N); caps.resize(N);
    for (int i = 0; i < N; ++i) cin >> cells[i];
    for (int i = 0; i < N; ++i) cin >> caps[i];

    int fireR = -1, fireC = -1;
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            cellId[i][j] = i * N + j + 1;
            if (cells[i][j] == 'Z') {
                fireR = i;
                fireC = j;
            }
        }
    }

    propagateFire(fireR, fireC);

    int totalNodes = 2 * N * N + 2;
    MaxFlowSolver solver(totalNodes, 0, totalNodes - 1);

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (isdigit(cells[i][j])) {
                int people = cells[i][j] - '0';
                solver.connect(0, cellId[i][j], people);
                propagateExit(i, j);
                for (int r = 0; r < N; ++r) {
                    for (int c = 0; c < N; ++c) {
                        if (isdigit(caps[r][c]) && exitDist[r][c] != -1 &&
                            exitDist[r][c] <= fireDist[r][c] && exitDist[r][c] <= Tmax) {
                            bool ok = true;
                            if (exitDist[r][c] == fireDist[r][c]) {
                                ok = false;
                                for (auto [nr, nc] : getNeighbors(r, c)) {
                                    if (exitDist[nr][nc] != -1 &&
                                        exitDist[nr][nc] < fireDist[nr][nc]) {
                                        ok = true;
                                        break;
                                    }
                                }
                            }
                            if (ok) {
                                solver.connect(cellId[i][j], N * N + cellId[r][c], people);
                            }
                        }
                    }
                }
            }
        }
    }

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (isdigit(caps[i][j])) {
                int cap = caps[i][j] - '0';
                solver.connect(N * N + cellId[i][j], totalNodes - 1, cap);
            }
        }
    }

    cout << solver.solve() << '\n';
}
